#!/usr/bin/env node
/**
 * Regenerates the offline tools of the preinstalled office Tool Pack:
 *   scripts/office-suite/src/*.mjs + pinned libraries (scripts/office-suite/package.json)
 *   -> packs/office-suite/bin/office.cjs (one self-contained CommonJS file)
 *   -> packs/office-suite/bin/BUILD.json (bundle SHA-256 and the bundled packages)
 *   -> packs/office-suite/THIRD_PARTY_LICENSES.txt (license texts of those packages)
 *
 * The generated files are committed: a source download, the offline kit and the competition
 * bundle need no build step and no npm access. scripts/check-office-suite.test.mjs fails
 * when the committed bundle does not match BUILD.json.
 *
 * Usage (developer machine with npm registry access):
 *   npm ci --prefix scripts/office-suite
 *   node scripts/build-office-suite.mjs
 */
import { createHash } from "node:crypto";
import { existsSync } from "node:fs";
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repository = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sources = path.join(repository, "scripts", "office-suite");
const pack = path.join(repository, "packs", "office-suite");
const modules = path.join(sources, "node_modules");
if (!existsSync(path.join(modules, "esbuild")))
  throw new Error("Run `npm ci --prefix scripts/office-suite` first (needs npm registry access)");

const require = createRequire(path.join(sources, "package.json"));
const esbuild = require("esbuild");
const output = path.join(pack, "bin", "office.cjs");
await mkdir(path.dirname(output), { recursive: true });
const result = await esbuild.build({
  entryPoints: [path.join(sources, "src", "office.mjs")],
  outfile: output,
  bundle: true,
  platform: "node",
  target: "node20",
  format: "cjs",
  minify: true,
  charset: "utf8",
  legalComments: "none",
  metafile: true,
  logLevel: "warning",
  banner: {
    js: "// Generated by scripts/build-office-suite.mjs from scripts/office-suite/src. Do not edit; see bin/BUILD.json and THIRD_PARTY_LICENSES.txt.",
  },
});

/** Package directory (…/node_modules/<name> or @scope/<name>) of every bundled input. */
const packages = new Map();
for (const input of Object.keys(result.metafile.inputs)) {
  const normalized = input.split(path.sep).join("/");
  const index = normalized.lastIndexOf("node_modules/");
  if (index < 0) continue;
  const parts = normalized.slice(index + "node_modules/".length).split("/");
  const name = parts[0].startsWith("@") ? `${parts[0]}/${parts[1]}` : parts[0];
  const directory = path.resolve(
    repository,
    normalized.slice(0, index + "node_modules/".length) + name,
  );
  if (!packages.has(directory)) packages.set(directory, name);
}
const bundled = [];
for (const [directory, name] of packages) {
  const manifest = JSON.parse(await readFile(path.join(directory, "package.json"), "utf8"));
  const files = (await readdir(directory)).filter((file) =>
    /^(licen[cs]e|copying|notice)(\.|$)/i.test(file),
  );
  const texts = [];
  for (const file of files.sort())
    texts.push((await readFile(path.join(directory, file), "utf8")).replace(/\r\n?/g, "\n").trim());
  bundled.push({
    name,
    version: manifest.version,
    license:
      typeof manifest.license === "string"
        ? manifest.license
        : (manifest.license?.type ?? manifest.licenses?.map((item) => item.type).join(" OR ") ?? "UNKNOWN"),
    text: texts.join("\n\n"),
  });
}
bundled.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : a.version < b.version ? -1 : 1));

const bytes = await readFile(output);
const build = {
  generator: "scripts/build-office-suite.mjs",
  sources: "scripts/office-suite/src",
  esbuild: esbuild.version,
  bundle: {
    file: "bin/office.cjs",
    bytes: bytes.length,
    sha256: createHash("sha256").update(bytes).digest("hex"),
  },
  packages: bundled.map(({ name, version, license }) => ({ name, version, license })),
};
await writeFile(path.join(pack, "bin", "BUILD.json"), `${JSON.stringify(build, null, 2)}\n`);
await writeFile(
  path.join(pack, "THIRD_PARTY_LICENSES.txt"),
  [
    "HarnessHub office-suite Tool Pack: third-party software bundled into bin/office.cjs",
    "",
    "jszip is dual licensed (MIT OR GPL-3.0-or-later); it is used here under the MIT license.",
    "",
    ...bundled.flatMap((item) => [
      "=".repeat(78),
      `${item.name} ${item.version} (${item.license})`,
      "=".repeat(78),
      item.text || "(The package ships no license file; see its package.json and repository.)",
      "",
    ]),
  ].join("\n"),
);
console.log(
  JSON.stringify({
    event: "office-suite.built",
    bundle: build.bundle,
    packages: bundled.length,
    warnings: result.warnings.length,
  }),
);
